"""Range/exact release-bank construction and fast suffix lookup."""
from collections import defaultdict

from .exact_keys import ExactKeySpace, interval_without_point, MAX_VALUE

DOMAIN_START = 0
DOMAIN_SIZE = MAX_VALUE + 1


def full_domains(patterns):
    return [tuple((int(lo), int(hi)) for lo, hi in pattern) for pattern in patterns]


def exact_domains(patterns):
    out = []
    for pattern in patterns:
        dom = []
        empty = False
        for lo, hi in pattern:
            parts = interval_without_point(int(lo), int(hi))
            if not parts:
                empty = True
                break
            dom.append(parts)
        out.append(None if empty else tuple(dom))
    return out


class MaskGroup:
    """Bitset interval matcher for equal-length interval patterns.

    Bit k corresponds to local pattern k.  For each coordinate position a
    table maps every possible encoded value to the bitset of patterns whose
    interval contains that value.
    """

    __slots__ = ('length', 'count', 'allmask', 'masks')

    def __init__(self, length, domains):
        self.length = int(length)
        self.count = len(domains)
        self.allmask = (1 << self.count) - 1
        masks = []
        if self.count:
            h = DOMAIN_SIZE
            for pos in range(self.length):
                events = [0] * (h + 1)
                for index, domain in enumerate(domains):
                    bit = 1 << index
                    for lo, hi in domain[pos]:
                        events[lo] ^= bit
                        events[hi + 1] ^= bit
                arr = [0] * h
                active = 0
                for value in range(h):
                    active ^= events[value]
                    arr[value] = active
                masks.append(arr)
        self.masks = masks

    def suffix_candidates(self, features, seen):
        length = self.length
        if seen < length or not self.count:
            return 0
        base = seen - length
        candidate = self.allmask
        for pos in range(length):
            candidate &= self.masks[pos][features[base + pos]]
            if not candidate:
                return 0
        return candidate

    def key_candidates(self, key):
        if not self.count:
            return 0
        candidate = self.allmask
        for pos, value in enumerate(key):
            candidate &= self.masks[pos][value]
            if not candidate:
                return 0
        return candidate


class RangeLookup:
    __slots__ = ('groups',)

    def __init__(self, kept_clusters, priority_rank):
        groups = defaultdict(list)
        for cluster in kept_clusters:
            groups[cluster.length].append(cluster)
        built = []
        for length, clusters in groups.items():
            # Global priority order is preserved inside each length.
            domains = full_domains([c.rng for c in clusters])
            study = MaskGroup(length, domains)
            ids = [c.cid for c in clusters]
            ranks = [priority_rank[c.cid] for c in clusters]
            built.append({
                'length': length,
                'mask': study,
                'ids': ids,
                'ranks': ranks,
                'minrank': ranks[0],
            })
        built.sort(key=lambda item: item['minrank'])
        self.groups = built

    def match(self, features, seen):
        best_rank = None
        best_cid = None
        best_length = None
        for item in self.groups:
            minrank = item['minrank']
            if best_rank is not None and minrank >= best_rank:
                break
            length = item['length']
            if seen < length:
                continue
            candidates = item['mask'].suffix_candidates(features, seen)
            if not candidates:
                continue
            bit = (candidates & -candidates).bit_length() - 1
            rank = item['ranks'][bit]
            if best_rank is None or rank < best_rank:
                best_rank = rank
                best_cid = item['ids'][bit]
                best_length = length
        if best_cid is None:
            return None
        return best_cid, seen - best_length


class ExactLookup:
    __slots__ = ('groups',)

    def __init__(self, tables):
        # tables: list of (length, {key: (rank,cid)})
        built = []
        for length, table in tables.items():
            if not table:
                continue
            minrank = min(value[0] for value in table.values())
            built.append((length, table, minrank))
        built.sort(key=lambda item: item[2])
        self.groups = built

    def match(self, features, seen):
        best_rank = None
        best_cid = None
        best_length = None
        for length, table, minrank in self.groups:
            if best_rank is not None and minrank >= best_rank:
                break
            if seen < length:
                continue
            key = tuple(features[seen - length:seen])
            value = table.get(key)
            if value is None:
                continue
            rank, cid = value
            if best_rank is None or rank < best_rank:
                best_rank = rank
                best_cid = cid
                best_length = length
        if best_cid is None:
            return None
        return best_cid, seen - best_length


def build_exact_bank(kept_clusters, cap, priority_rank):
    """Return (actual_or_cap_plus_one, exact lookup tables)."""
    groups = defaultdict(list)
    for cluster in kept_clusters:
        groups[cluster.length].append(cluster)

    spaces = {}
    total = 0
    for length in sorted(groups):
        patterns = [cluster.rng for cluster in groups[length]]
        space = ExactKeySpace(patterns, cap)
        spaces[length] = space
        total += space.count()
        if total > cap:
            return cap + 1, {}

    tables = {}
    for length in sorted(groups):
        space = spaces[length]
        keys = space.keys()
        if not keys:
            continue
        clusters = sorted(groups[length], key=lambda c: priority_rank[c.cid])
        domains = exact_domains([c.rng for c in clusters])
        usable = []
        ids = []
        ranks = []
        for cluster, dom in zip(clusters, domains):
            if dom is None:
                continue
            usable.append(dom)
            ids.append(cluster.cid)
            ranks.append(priority_rank[cluster.cid])
        if not usable:
            continue
        mask = MaskGroup(length, usable)
        table = {}
        for key in keys:
            candidates = mask.key_candidates(key)
            if not candidates:
                # This can only happen for an empty-domain pattern, which was
                # removed from the mask group; a union key always has a cover.
                continue
            bit = (candidates & -candidates).bit_length() - 1
            table[key] = (ranks[bit], ids[bit])
        if table:
            tables[length] = table
    return total, tables
